INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('indra-no-hikari', 48461, '1987-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p7czveciwriq2r252byy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indra no Hikari', 'Around the year 2000, mankind departs a depleted earth and travels through space to the plant Ibaru some 8,500 light years away. There, people live peacefully under the protection of a god whose power source is the Light of Indora. However, a demon siphons the light away from the planet and the god begins to slumber. The surface of the planet transforms into a vast desert and monsters begin to appear. The player must quest to put an end to the demon and restore the Light of Indora to the god that protects the planet.' FROM games WHERE igdb_id = 48461 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48461 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 48461 AND c.slug = 'kemco' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 48461 AND p.igdb_id = 99 ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'ja', 'Japanese', false, false, true FROM games WHERE igdb_id = 48461 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kinnikuman-kinniku-sei-oui-soudatsusen', 41324, '1987-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/xji5kyfhee7ud8xyiasn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwzci.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinnikuman: Kinniku-sei Oui Soudatsusen', 'Being the only back-to-back two-time champion in Chojin Olympics history and having defeated the Akuma Chojins, the Devil Knights, and having won the Dream Choujin Tag Tournament against the Perfect Choujins, Kinniku Suguru had proven himself worthy to take over his father''s throne. However, the 5 Evil Gods feared that Kinnikuman taking the throne would be a threat to their evil plans. FIGHT! And help Suguru take his rightful place on the throne.' FROM games WHERE igdb_id = 41324 ON CONFLICT (game_id, language_code) DO NOTHING;
