INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('testament--1', 237303, '1987-10-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co657k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scl9m3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Testament', 'As told by the ancient scroll Lyle found on his travels, a great five-headed Pentadragon once ruled the Diodoran continent with its legions of monsters. The heavens struck them down, sinking their land far into the earth...until now. With Pentadragon and Diodoran resurfacing to torment the world again, Lyle ventures out with gun and gear to rid this realm of evil and fulfill the gods'' prophecy. Testament is a top-down, multi-scrolling shoot-''em-up adventure with several complex levels to explore. You acquire new weapons, items, and bonuses along paths strewn with enemies and hazards to encounter. Each stage features multiple boss fights and an assortment of secrets, either threatening or aiding your quest. You have limited lives and continues to work with, so play carefully and methodically to survive your expedition. This game led to the founding of a studio called Glodia, and it later received a Game Boy spiritual sequel simply called Pentadragon.' FROM games WHERE igdb_id = 237303 ON CONFLICT (game_id, language_code) DO NOTHING;
