INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Secret of Little Hodcome', 'The Secret Of Little Hodcome is a text adventure from Zenobi Software with mild horror elements. Once upon a time the player had a distant, and forgotten relative. That relative is no more meaning that the player has inherited a cottage in the tiny hamlet of Little Hodcome. After a bit of not-too-productive research, ''Where is this place?'', off you trot to meet the estate agent. Naturally, this being an adventure, all is not well in the English countryside and the object of the game is to uncover and vanquish whatever evil force lurks there.' FROM games WHERE igdb_id = 232554 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 232554 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
