INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-train-escape-to-normandy', 47183, '1987-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xn0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru7s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Train: Escape to Normandy', 'The Train: Escape to Normandy is a video game released by Accolade in 1988 and themed loosely on the motion picture The Train, starring Burt Lancaster. In the video game, the player assumes the role of a train hijacker who has commandeered a steam train to escape Nazi Germany during World War II. When the train is in motion the player must maintain the correct speed, steam pressure and other operational parameters of the train; also, the player must attempt to shoot down Nazi fighter planes which occasionally strafe the train by aiming and firing anti-aircraft guns mounted to the engine of the train. When the train occasionally stops briefly for resupply at various train stations, the player also must provide cover fire against attackers in the station buildings for comrades resupplying the train. The Train was initially released for several 8-bit computer platforms, including the Commodore 64 and Apple II series, on which it was fairly popular. The game was also later released on IBM PC.' FROM games WHERE igdb_id = 47183 ON CONFLICT (game_id, language_code) DO NOTHING;
