INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bikkuri-man-world', 42085, '1987-11-30', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bikkuri Man World', 'Despite being Hudson’s Vol.2, this was in fact released almost a month before The Kung Fu. It’s a conversion of what most people know as Wonder Boy in Monster Land, and it’s as perfect a conversion as you’re likely to get. This game takes a different pace from the first Wonder Boy game, being more of an adventure with a slower pace and more strategy. You start the game with barely a thread on and are given a sword by some wise looking dude who lives in a tree - so far so good. It is then your task to travel through the various platform-based levels defeating monsters and evil bosses along the way. Each enemy you kill leaves behind a coin or money bag (these are also at various hidden locations if you jump at the right spot) and shops will offer you armour, shields, weaponry and go-faster shoes. You can also pop into a bar and top up your energy if you can afford it. Levels are time limited (shown by an egg-timer on the left) so you need to be quick, or energy is taken away from your heart meter.' FROM games WHERE igdb_id = 42085 ON CONFLICT (game_id, language_code) DO NOTHING;
