INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Dark Castle', 'Beyond Dark Castle is a classic platformer for the Macintosh. The game puts the player in the role of Prince Duncan who, once again, must defeat the evil Black Knight through a series of challenges leading up to the final showdown with the Black Knight himself. A colorized Mac version was planned by Delta Tao Software but was cancelled.' FROM games WHERE igdb_id = 11957 ON CONFLICT (game_id, language_code) DO NOTHING;
