INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('how-to-be-a-complete-bastard', 13882, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co75pp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'How to Be a Complete Bastard', 'This game is based around cult ‘alternative comedian’ Ade Edmondson’s book of the same name. Having gate-crashed a party full of sophisticated well-behaved types, you must do everything you can to be seen as hateful, yobbish and immature – a Complete Bastard. The house has several rooms, each of which are filled with objects which are of use, as well as unlimited supplies of food, alcohol and coffee, which control how drunk you are at a time – some awful actions force you to be sober, others force you to be drunk. The game also displays whether you need the toilet (or, more accurately, any part of the house that would cause offence), whether you need to fart, and how strong-smelling these are. The rooms can all be viewed from multiple angles, and 2 can be viewed at a time through a split-screen view. To win, you need to prove to all 16 party guest that you are a complete bastard.' FROM games WHERE igdb_id = 13882 ON CONFLICT (game_id, language_code) DO NOTHING;
