INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sky-fox', 39301, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8kqo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct9zs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Fox', 'The game is a vertical shoot ''em up in the style of Galaga and Phoenix,but with eight-way movement across the screen and parallax scrolling for the stars backgrounds. At the player''s disposal to fight the approaching enemies, some of them made in pseudo-depth 2.5D graphics with scaled sprites, is a small space fighter capable of firing two types of projectiles: the unlimited but slow rockets and the fast laser shots that are limited by draining the ship''s power. The power can be refilled, and the ship itself upgraded, through collecting the power-ups that appear after destroying certain enemies. The game can be played by up to two players in alternating turns. Similar as in Gorf, it features several different types of waves (stages). For instance, one stage features space witches saddle-perched on either serpentlike Chinese dragons or Western-style winged dragons: the dragons must to be hit repeatedly in the weak point of their heads to be killed, after which the riders themselves can be shot for a score bonus. The player progresses through most of them by either destroying all the enemies (resulting in the score bonus and power-up awards) or alternatively just surviving their attacks for a long enough time.' FROM games WHERE igdb_id = 39301 ON CONFLICT (game_id, language_code) DO NOTHING;
