INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ikinari-musician', 48462, '1987-03-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o0l.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikinari Musician', 'Ikinari Musician provides a piano-like keyboard, a treble clef on the staff to show note location, a 5-channel Backing track, 4 timbre choices, and controllers to manipulate common synthesizer parameters such as release and attack, LFO, etc. It also provides recording and play back function. The player has many choices of styles of the backing track, from popular styles such as Rock, Techno, and Jazz, to various ethnic flavors such as Bossa, Rio, Japan, India, Arabia, etc. The backing tracks representing the styles use familiar elements to make the game more accessible to the general audience. For example, in the Scotland style Cadence to Arms, a familiar bagpipes tune, is used. Most backing tracks loop around one or two chords, allowing an open improvisation on the main keyboard. Once the style is chosen, the main keyboard is masked in the way that only the scale that easily fits into the style is available, e.g. blues scale, pentatonic scale, etc. The keyboard is controlled by the UP-DOWN or LEFT-RIGHT d-pads on the game controller so there is no way to play leaps in the scale. Due to the hardware limitation, the sound produced is the typical 8-bit chiptune music.' FROM games WHERE igdb_id = 48462 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48462 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
