INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ramparts', 40942, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wllzhmel9hgxqkifijib.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ramparts', 'Not to be confused with Atari Games'' Rampart, Ramparts is in fact a clone of Bally Midways'' Rampage, but with a medieval theme, and players are giant knights instead of monsters. The game is for one or two players simultaneously.  The game takes place on a single screen, where the player(s) can move left and right on one foreground plane, and the object is to destroy a castle, each phase, by scaling and punching the individual buildings until each, and all collapses. Buildings will often overlap, requiring some to be taken down before others. Players will be harassed by witches, goblins, archers and the like.' FROM games WHERE igdb_id = 40942 ON CONFLICT (game_id, language_code) DO NOTHING;
