INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Heli', 'It is your mission, ''Mr. Heli'' our hero, to unmask ''The Muddy'' who is hiding deep underground and rescue the planet. Clear all the zones including floating green islands, moving rock beds, mysterious underground temples, and much more! The exhilarating air battle and stunning graphics capture the true character of the arcade machine. Play sharp, steer right, keep up with the fight!' FROM games WHERE igdb_id = 10446 ON CONFLICT (game_id, language_code) DO NOTHING;
