INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knightmare II: The Maze of Galious', 'Knightmare II: The Maze of Galious (Majou Densetsu II: Galious no Meikyuu in Japan) is a screen by screen action adventure platformer released originally for MSX in 1987. It can be considered an early example of a Metroidvania game with free exploration of a large castle.' FROM games WHERE igdb_id = 36671 ON CONFLICT (game_id, language_code) DO NOTHING;
