INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vaxol: Heavy Armed Storming Vehicle', 'Vaxol is a Space Harrier-inspired game where players control a heavily armed robot traversing a hazardous planetary surface. Waves of enemies reminiscent of Space Harrier appear, and players can fly across the screen to avoid obstacles. Unlockable weapon systems enhance gameplay, while defeating giant bosses awaits at each level''s end. With a single life at the start, Vaxol offers a challenging experience.' FROM games WHERE igdb_id = 41785 ON CONFLICT (game_id, language_code) DO NOTHING;
