INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino', 'Dino and the Saurus Races is a side-scrolling platform game. You are a dinosaur rider and your goal is it to get as far as possible to get as many points as possible. You hop over gaps and mushrooms and avoid birds (or pteranodons) and spiders.' FROM games WHERE igdb_id = 100355 ON CONFLICT (game_id, language_code) DO NOTHING;
