INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('f-1-spirit-the-way-to-formula-1', 41649, '1987-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hk5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-1 Spirit: the Way to Formula-1', 'F-1 Spirit: The Way To Formula-1 is a top down Formula One Racing game, developed and published by Konami, which was released for the MSX in Japan and Europe in 1987. The game engine is very similar to Konami''s Road Fighter. It also features Konami''s custom sound chip called Konami SCC (a five-channel chip that compliments the three-channel PSG chip of the MSX computer system, or in other words, a sound custom chip that brings five voices more to the three voices of the PSG sound chip on the system), and great MSX1 graphics to go with it. It was one of the first ROM on MSX with this sound feature. Together with its "3D" spinoff (F-1 Spirit: 3D Special), F-1 Spirit: The Way To Formula-1 was the most extended racing game Konami released for the MSX.' FROM games WHERE igdb_id = 41649 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41649 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
