INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('roadwar-europa', 12747, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ij.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roadwar Europa', 'Roadwar Europa starts off with you as the leader at a large road gang equipped with cars trucks, and motorcycles of your own design Transfer your crew from Roadwar 2000 or start from scratch and create a new elite band. By fighting for new recruits, vehicles, supplies, ammunition and medicine, you''ll maximize your chances for survival in this dangerous new world. You''ll also be building up your forces to prepare for the final roadwar against the powerful terrorist leaders - a battle whose outcome will determine the future of all Europe.' FROM games WHERE igdb_id = 12747 ON CONFLICT (game_id, language_code) DO NOTHING;
