INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokkaido Rensa Satsujin: Okhotsk ni Kiyu', 'A man''s corpse is discovered near a sea wharf in Tokyo Bay. While the police investigates, a 2nd and 3rd murder occurs one after another. You begin your investigating with Shunsuke Saruwatari, a detective from the Kushiro station, and seek the truth to discover the criminal''s motivation. An examination of the relation between the victims exposes a important details from the past.' FROM games WHERE igdb_id = 48360 ON CONFLICT (game_id, language_code) DO NOTHING;
