INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('final-assault--1', 39115, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9fbf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvgbx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Assault', 'Final Assault is a mountaineering simulation game with a realism that will surprise you. You will find all the elements that characterize a mountain route: duration (day and night), season, snow consistency, fatigue, survival, dangers, impressive landscapes, abysses, glaciers, etc. From the beginning, the player must equip the climber with everything he needs to climb the chosen route. Each route is made up of a part of walking on the glacier, another of progression on the snowy slope and another on the rock. The danger is dying of cold and fatigue.' FROM games WHERE igdb_id = 39115 ON CONFLICT (game_id, language_code) DO NOTHING;
