INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AshGuine Story III: Fukushuu no Honoo', 'Seven years ago, the father and mother of the Reptile-Human ASHGUINE were killed by the Ghouls. But now, changing his appearance with the help of an old machine, Ashguine is the only one to launch a counter-attack on the enemy armies. It''s time for revenge.' FROM games WHERE igdb_id = 41720 ON CONFLICT (game_id, language_code) DO NOTHING;
