INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.B. Harold Series #2: Manhattan Requiem - Angels Flying in the Dark', 'The second game in the J.B. Harold series. 24 year old pianist Sarah Shields was found dead after falling from the 25th floor of her apartment window. The cause of death was a fractured skull from the horrific impact. With no evidence of foul play, an act of suicide was the best explanation - but J.B. Harold thinks otherwise. Having recieved a letter from Sarah beforehand, the famous detective heads towards New York City to find the truth.' FROM games WHERE igdb_id = 62588 ON CONFLICT (game_id, language_code) DO NOTHING;
