INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('operation-fireball', 293744, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91as.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Fireball', 'Operation Fireball is a horizontal scrolling shooter viewed from above at an elevated angle, with the screen scrolling constantly from left to right as you use various modes of transport to get to a base to blow up a submarine. Between each mode of transport is a small animated scene as you move from one to the next and the modes are car, speedboat, ski, motorbike and helicopter. You must shoot or avoid the enemy in various vehicles or on skis, as well as avoid obstacles like rocks, oil patches and trees. Helicopters fly overhead and drop bombs while missiles fly from the right to the left and can only be avoided. If you are hit by anything then you lose part of a shield gauge but when not being hit increases it and if it empties then it is game over.' FROM games WHERE igdb_id = 293744 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 293744 AND c.slug = 'alternative-software-ltd--1' ON CONFLICT DO NOTHING;
