INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blackjack-academy', 12352, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/llfycrrsxgnqp80yzilc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nlnurb39ogydd8pd2sfg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackjack Academy', 'Everything you wanted to know about blackjack but were too shy to ask. From the novice to the pro, BlackJack Academy will help you learn to play blackjack or brush up before you hit the tables. BlackJack Academy features a five player table so you and four friends can all play, multiple table rules like Las Vegas, Reno, Atlantic City as well as the ability to specify your own table rules. BlackJack Academy offers on-line help for all the different play options and will even give you the optimal play for the current hand if you like. Color selectability, game save and retrieve, and different play strategies are some of the other features of Blackjack Academy. We are sure you and your friends will have many hours of fun and education with Blackjack Academy. Microillusions is proud to have you sitting at our table. Other features include: sound toggle, play speeds from slow to very fast, card counting toggle, player card total toggle, money management guide, any dollar amount can be selected from table minimum to $9999.00 (individual totals can get to be much, much higher during the play of the game), as well as a pocket size quick reference guide for optimal play when you are at the tables.' FROM games WHERE igdb_id = 12352 ON CONFLICT (game_id, language_code) DO NOTHING;
