INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SRD: Super Real Darwin', 'SRD: Super Real Darwin is a 1987 vertical scrolling shooter arcade game developed and published by Data East. It is the sequel to Data East''s 1986 arcade game, Darwin 4078. The player takes control of a small fighter ship capable of mutating into different shapes. The ship''s appearance will change with upgraded weapons as the player obtain more power-ups.' FROM games WHERE igdb_id = 28022 ON CONFLICT (game_id, language_code) DO NOTHING;
