INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('addicta-ball', 41647, '1987-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6enqcvskreej7fqank.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Addicta Ball', 'Addicta Ball is a Breakout clone with a twist. Players control a paddle to break down a wall of different block by bouncing a ball against them, but instead of removing them to clear a level, players need to make a path for the paddle to pass through. As time goes on, the bricks move lower down the screen so the path needs to be created as long as there is an opportunity. The game is over when the bricks hit the paddle. There are different kinds of power-ups, weapons, a thruster to move over the screen, and a barrier at the bottom of the screen that prevents the ball from disappearing, but it degrades over time.' FROM games WHERE igdb_id = 41647 ON CONFLICT (game_id, language_code) DO NOTHING;
