INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Punch-Out!!: Shouhin-ban', 'Also known by the unofficial titles of Punch-Out!! Gold and Punch-Out!! Special, with the in-game title of simply Punch-Out!!, recently released on the Japanese Nintendo Switch Online as Punch-Out!!: Shouhin-ban (Prize Version), this was the first released version of Punch-Out!! for the NES/Famicom, which was released in Japan, as a prize for the participants of the official NES Open Tournament Golf (Golf Tournament US Course) competition. The main differences from the later versions is that the Dream Bout with Mike Tyson or Mr. Dream didn''t exist yet, and Mr. Macho Man was the last opponent.' FROM games WHERE igdb_id = 329510 ON CONFLICT (game_id, language_code) DO NOTHING;
