INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Subnodule', 'You control a submarine in hostile waters. Sharing the deep sea with you are several dangerous creatures such as jellyfish, eels, sharks and the mysterious X-Sub. Destroy everything to reach the next level. This game has intermissions as well.' FROM games WHERE igdb_id = 79587 ON CONFLICT (game_id, language_code) DO NOTHING;
