INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('return-of-the-mutant-camels', 40961, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hp7.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return of the Mutant Camels', 'Jeff Minter''s third camel-themed game (after Attack and Revenge) is again a horizontally scrolling shoot ''em up, taking place over 100 levels. 6,000 years ago, mankind fought the forces of Zzyax, using mutated forms of common animals. Now, the Zzyaxians are back, and the 90-foot camels must defend a planet no longer accustomed to warfare. The Zzyaxian hordes consist of typical Minter zaniness. Postboxes and letters, Pacman ghosts and microchips are all out to get you. The game allows you to fire in any direction, by moving the joystick while holding down the fire button. Additionally, you can drop miniature versions of yourself, as bombs. After completing a level or losing a life, the player can move to a level adjacent to the current one within a 10x10 grid. You can also purchase improved shields, energy recharges, or improved weaponry such as bigger or ''smart'' bullets.' FROM games WHERE igdb_id = 40961 ON CONFLICT (game_id, language_code) DO NOTHING;
