INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('uchuusen-cosmo-carrier', 48559, '1987-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3hsf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arye0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uchuusen Cosmo Carrier', 'Uchuusen: Cosmo Carrier is an action strategy game where you pilot the titular Cosmo Carrier and combat aliens while gaining intelligence on the solar system, the planets and its moons. Information you gather from satellites with your deployable Mechs will help you find the alien force and destroy them. Once deployed your Mechs walk around the surface and fight turrets and find items/clues. Your viewscreen is where you target alien space-craft, astronauts, moons, and planets and interact with them. The interactions allowed are: Missile, Beam, Shiled(SIC), Move, Communicate, Computer, Parts, and State. Missile launches a rocket with adjustable strength at your target. Beam shoots a laser weapon at your target. The misspelled Shield function lets you decide if you want your shields on or not. Move button has two different sub selections; Warp and Land. Warp lets you travel from planet to planet while Land lets you deploy one of your Mechs on to the surface of a satellite or enemy cruiser. Communicate lets you do just that, communicate with planets and other vehicles. Computer gives you read-outs on targeted planets and vehicles. The Computer also is where you perform repairs on your ship or Mechs. Parts lets you see what weapons you have loaded. Finally, State, gives you detailed information pertaining to shields, weapons etc of your Cosmo Carrier and three Mechs; Gravity, Blizzard and Field.' FROM games WHERE igdb_id = 48559 ON CONFLICT (game_id, language_code) DO NOTHING;
