INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trantor: The Last Stormtrooper', 'Betrayed by his people, TRANTOR is abandoned alone on an Alien planet. His only chance of escape is to activate the planet''s main computer that lies within the terminal building. Spectacular sound and graphics transport you light years to the future. Armed only with a flame thrower, fight your way to freedom as TRANTOR... THE LAST STORMTROOPER!' FROM games WHERE igdb_id = 39097 ON CONFLICT (game_id, language_code) DO NOTHING;
