INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hikari-no-senshi-photon-the-ultimate-game-on-planet-earth', 48491, '1987-09-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co742a.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hikari no Senshi Photon: The Ultimate Game on Planet Earth', 'Photon: The Ultimate Game on Planet Earth is an adventure game developed for the Famicom by Takara, and published in 1987. The English name of the game has special significance, since "Photon: The Ultimate Game on Planet Earth" is also the name of the first commercial version of a game commonly known today as Laser Tag. However, besides the name, and the fact that you play a character who fires a Photon gun, any further connection between the live action game and this video game is unknown. In the video game, you play a soldier who must navigate through several different floors of a dungeon which contains items and traps. The player must figure out how to maneuver through the dungeon in an effort to collect various items that will expand his ability to search, and find various disks which contain hints and messages to further aid the player. The game is played from a third-person behind-the-shoulder perspective and contains pseudo-3D visuals. This game was never released outside of Japan.' FROM games WHERE igdb_id = 48491 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 48491 AND c.slug = 'takara' ON CONFLICT DO NOTHING;
