INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tanigawa-kouji-no-shogi-shinan-ii-meijin-he-no-michi', 41382, '1987-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ii8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gv6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tanigawa Kouji no Shogi Shinan II: Meijin he no Michi', 'An instructional Shogi game, that teaches the Japanese version of chess. It is hosted by Tanigawa Kouji, a top-tier Shogi player. It was released for the Famicom Disk System, NES and MSX. Shogi, a Japanese board game similar to chess, is a board game as popular as Mahjong in Japan. Tanigawa Kouji no Shogi Shinan II ("Tanigawa Kouji''s Instructional Shogi II") is the second in a series of instructional Shogi games hosted by then-top tier champion and expert Shogi player Tanigawa Kouji to help improve the player''s game. The first Tanigawa Kouji no Shogi Shinan was only released on MSX home computers, though this game first came out on the Famicom Disk System in 1987. It would later receive additional versions for the MSX and the regular cartridge-based Famicom in 1988. There also exists a second Famicom Disk System version, released after the MSX and Famicom ports, that contains additional puzzle arrangements. The third game in the series would only be released on the Famicom. Neither this game nor any of the games in the series were ever released outside of Japan.' FROM games WHERE igdb_id = 41382 ON CONFLICT (game_id, language_code) DO NOTHING;
