INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('legacy-of-the-ancients', 19794, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/j7dcvzz2sbrjzhjckrs3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mflvyyb2t21umcd6cldv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of the Ancients', '"The player takes on the role of a young shepherd who finds and loots a recently dead body while on a first trip to the city, taking a black disk, a bracelet, and a leather scroll. The Galactic Museum mysteriously appears to the player after collecting these items. The player learns that by taking these items, he has become the next in a line of adventurers attempting to destroy the Wizard''s Compendium, the leather scroll the player picked up.  The museum has various display cases that require the insertion of special coins of various types to access. Some coins can be bought in random encounters with NPCs, some can be found as loot after combat, and some coins can only be found at the bottom level of various dungeons, meaning the player cannot proceed beyond a certain point until that dungeon is finished.  Unlike many RPGs, the game does not use an experience point system. The player gains levels only through the successful completion of various quests.  The game is mostly in top-down style for the world maps, towns, and castles, but switches to a 3D style in the dungeons and in the museum.  Several different areas of the game, like games in towns and certain museum displays, allow the character to play in special mini-games, which, if done successfully, will permanently increase attributes. Also, various casinos about the towns let players gamble to win money. It is also possible to rob banks in cities, but this attracts the attention of the town guards, who will remember the robbery until the player enters another town."' FROM games WHERE igdb_id = 19794 ON CONFLICT (game_id, language_code) DO NOTHING;
