INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Adventure', 'Dark Adventure is a dimetric action-adventure game produced by Konami that was released for the arcades in North America in 1987.[3] It was the first arcade game by Konami that allowed up to three players simultaneously. The game was also released as Majū no Ōkoku in Japan and as Devil World in other countries outside North America, although these versions feature significant gameplay differences and only allow up to two players.' FROM games WHERE igdb_id = 38529 ON CONFLICT (game_id, language_code) DO NOTHING;
