INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firezone', '2160. Beam technology, energy shields, and ground-skimming propulsion systems have revolutionized ground combat into high-speed, wide-ranging battles. World powers like the Pacific Combine and the European League spar and vie for territory with Grav tanks, striders, and Leviathans. Take the role of a commander overseeing one of these skirmishes and match your tactical wits with the computer or another player.' FROM games WHERE igdb_id = 74397 ON CONFLICT (game_id, language_code) DO NOTHING;
