INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spelunker II: Yuusha he no Chousen', 'Spelunker II: Yuusha he no Chousen is a Japan-exclusive action video game released for the Family Computer in 1987. An unofficial translation to English was made as a ROM hack. Despite being titled as a sequel to Spelunker, Spelunker II: Yūsha e no Chōsen features vastly different gameplay. There was a separate arcade sequel, titled Spelunker II: 23 no Kagi, which features similar gameplay to the first Spelunker game as well. The two Spelunker II games are separate entries in the series and are not related.' FROM games WHERE igdb_id = 78887 ON CONFLICT (game_id, language_code) DO NOTHING;
