INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hi-no-tori-houou-hen', 41694, '1987-04-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co967f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3u72.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hi no Tori: Houou-hen', 'Phoenix is about reincarnation. Each story generally involves a search for immortality, embodied by the blood of the eponymous bird of fire, which, as drawn by Tezuka, resembles the Fenghuang. The blood is believed to grant eternal life, but immortality in Phoenix is either unobtainable or a terrible curse, whereas Buddhist-style reincarnation is presented as the natural path of life. Hi no Tori is an Action game, developed and published by Konami, which was released in Japan in 1987.' FROM games WHERE igdb_id = 41694 ON CONFLICT (game_id, language_code) DO NOTHING;
