INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiss of Murder: Another Story of Manhattan Requiem', 'Kiss of Murder, is set in a parallel world to Manhattan Requiem, and while featuring the same set of characters as that title, has a completely different scenario. Early releases of the game were addons to "Manhattan Requiem" and used its graphical data. Later iterations became stand-alone.' FROM games WHERE igdb_id = 74889 ON CONFLICT (game_id, language_code) DO NOTHING;
