INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fairy Pinball: Yousei-tachi no Pinball', 'An adult pinball game in which you can play two tables and try to get a high enough score to watch a girl undress. The two tables are a space based one called Asteroid, and a naval war based one called Midway.' FROM games WHERE igdb_id = 41359 ON CONFLICT (game_id, language_code) DO NOTHING;
