INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-yakyuu-family-stadium-87', 48827, '1987-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kkdooslw6ngurje9cdqd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdsy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Yakyuu Family Stadium ''87', 'Not so much a sequel to Pro Yakyuu Family Stadium than an enhanced rerelease with updated rosters. It was published by Bandai for the Famicom in late 1987. Pro Yakyuu Family Stadium ''87 is the second game in Namco''s long running Family Stadium series, also known as Famista. It''s a traditional baseball game that allows one human player against the CPU, two competing human players and two competing CPU players in a "Watch" spectator mode. Rather than being a full sequel to Pro Yakyuu Family Stadium the game is instead an updated version of the original, which was reflected in its lower price at release. It adds a few features and updates the official rosters for the athletes, but is functionally identical to the original Family Stadium. This specific type of annualization would become common practice for sports game franchises such as Madden NFL and NHL. It''s worth noting that this game is unrelated to R.B.I. Baseball 2 from Tengen. The original R.B.I. Baseball and Family Stadium were one and the same, the former receiving a name change to appeal to a Western audience, but after that initial game both franchises diverged. R.B.I. Baseball specifically favored more realistic looking athlete sprites while Family Stadium would persist with the cartoonish "super deformed" sprites.' FROM games WHERE igdb_id = 48827 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 48827 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
