INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bureaucracy', 12618, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co325a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/klw49sqh123eu8hjrmuw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bureaucracy', 'Bureaucracy is an interactive fiction computer game released by Infocom in 1987, scripted by popular comic science fiction author Douglas Adams. The player is challenged to confront a long and complicated series of bureaucratic hurdles resulting from a recent change of address. Mail isn''t being delivered, bank accounts are inaccessible, and nothing is as it should be. The game includes a measure of simulated blood pressure which rises when "frustrating" events happen and lowers after a period of no annoying events. Once a certain blood pressure level is reached, the player suffers an aneurysm and the game ends. While undertaking the seemingly simple task of retrieving misdirected mail, the player encounters a number of bizarre characters, including an antisocial hacker, a paranoid weapons enthusiast, and a tribe of Zalagasan cannibals. At the same time, they must deal with impersonal corporations, counterintuitive airport logic, and a hungry llama.' FROM games WHERE igdb_id = 12618 ON CONFLICT (game_id, language_code) DO NOTHING;
