INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ark Area', 'Ark Area is a scrolling futuristic shoot ''em up arcade game released by UPL in 1987 in Japan only. You control a spacecraft and shoot enemies, collect power-ups, and defeat bosses to advance up to 23 levels. It is the sequel to the video arcade game Nova 2001.' FROM games WHERE igdb_id = 40016 ON CONFLICT (game_id, language_code) DO NOTHING;
