INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tantei-jinguji-saburo-shinjuku-chuuou-kouen-satsujin-jiken', 41412, '1987-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29tw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3t9d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Shinjuku Chuuou Kouen Satsujin Jiken', 'The first installment in the long-running Tantei Jinguuji Saburo (Jake Hunter) series about the mystery behind the death of a young woman whose corpse was discovered in Shinjuku Central Park. Tantei Jinguuji Saburo: Shinjuku Chuo Koen Satsujin Jiken ("Detective Saburo Jinguuji: Shinjuku Central Park Murder Mystery") is the first in a long-running series of crime-themed adventure games from Data East regarding the detective Saburo Jinguuji, or Jake Hunter as he is known in the West. As with all the games that follow, the goal of the game is to discover the perpetrator behind a murder by talking to witnesses and suspects, gathering clues and deducing facts about the case. The player can use a menu of options with which to control Detective Jinguuji''s investigation, such as "Talk" and "Look" commands to get a better sense of the world of the game.' FROM games WHERE igdb_id = 41412 ON CONFLICT (game_id, language_code) DO NOTHING;
