INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shiryou Sensen: War of the Dead', 'This horror action RPG revolves around a female SWAT member named Lila who must rescue survivors in an isolated monster-infested town. As the plot unfolds, it is later revealed that the monsters have come from a portal to another world and the family that has secretly protected it for generations.' FROM games WHERE igdb_id = 41736 ON CONFLICT (game_id, language_code) DO NOTHING;
