INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meikyuu Jiin Dababa', 'A young man''s significant-other is kidnapped by an evil wizard. He must then tackle the four areas of the labyrinth temple of Dababa to rescue her. In order to accomplish this task, the player cannot simple move across the floor. Rather, the player and all of the enemies hop from one square tile to another, throughout the game.' FROM games WHERE igdb_id = 41290 ON CONFLICT (game_id, language_code) DO NOTHING;
