INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('toki-no-tabibito-time-stranger', 48879, '1987-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/jdmfbo5q5olllsmzzwgh.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toki no Tabibito: Time Stranger', 'An adventure game based on an anime film of the same name, published for the Famicom by Kemco. Toki no Tabibito "Time Stranger" is an adventure game with a heavy emphasis on text commands and dialogue, similar to other NES adventure games like Portopia Serial Murder Case or Hokkaido Serial Murders: Fade to Okhotsk. Unlike Portopia and its sequels, there is very little detective work to be done. The player simply visits important people throughout Japanese history as a time-travelling cop, answering their questions and incrementally moving forwards through time towards the present. Most of the game is depicted in a first-person mode where the other person sits across from the main character, who then asks and answers questions. There are a few third-person sequences where the player must get back inside their spaceship-like time machine before it leaves. While there are a few branching paths depending on dialogue choices taken, the game''s narrative is fairly linear.' FROM games WHERE igdb_id = 48879 ON CONFLICT (game_id, language_code) DO NOTHING;
