INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S.M.A.S.H.E.D.', 'Pigseye Peers is a newly-qualified surgeon sent to join the mobile military hospital unit in Korea - the Strangest Mobile Army Surgical Hospital East of Detroit, or S*M*A*S*H*E*D for short. Thus, the game is a clear spoof of the very popular TV series, M*A*S*H*. It is an adventure using text inputs with occasional graphics.' FROM games WHERE igdb_id = 55108 ON CONFLICT (game_id, language_code) DO NOTHING;
