INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zombie Hunter', 'Zombie Hunter is an action RPG exclusively published in Japan. It was developed by a Japanese gaming magazine known as Hi-Score. The player must complete six sidescrolling levels and in each level, the player is presented with a number of fights that prevent you from making progress until all of the enemies have been defeated or chased away.' FROM games WHERE igdb_id = 48623 ON CONFLICT (game_id, language_code) DO NOTHING;
