INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazee Rider', 'Crazee Rider is the spiritual successor to Superior Software''s Overdrive. Originally envisioned as a car racing game it was turned into a motorcycle racer during development. Players need to race opponents over different tracks, starting out at the 60th position. To progress the player has to end in the top six of the pack in a single lap. Compared to Overdrive there are more opportunities to avoid opponents and tracks also have bends.' FROM games WHERE igdb_id = 349898 ON CONFLICT (game_id, language_code) DO NOTHING;
