INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Harrier', 'While based on the arcade original, the Sharp X68000 version adds "Haya-Oh," the final boss of the Sega Master System port. The ending was also extended, with an epilogue followed by the names of all the enemies the player fought. The checkerboard floor has also been simplified into a set of horizontal lines.' FROM games WHERE igdb_id = 341883 ON CONFLICT (game_id, language_code) DO NOTHING;
