INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('toki-no-senshi-chrono-soldier', 40472, '1987-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pjzvf2yfl4b3vqgqlqkv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z9y6ssjdfuszpnrrfc1s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toki no Senshi: Chrono Soldier', 'The mid-eighties saw the inception of a genre known as run-and-guns, which were popularized by the likes of Capcom''s Commando and SNK''s Ikari Warriors. At their base, these games were akin to shoot-em-ups, except they didn''t take place in airplanes or starcrafts as was the norm of the time. Most of them did not scroll automatically and allowed the player a bit more breathing room hence, but they still pressured players with lots of bullets and aggressive enemies. Most big companies offered at least one top-down on-foot shooter, Sega naturally included. Their best-known contribution to that front in the eighties was Alien Syndrome, their tribute to the Alien series which involves two soldiers destroying frightening xenomorphs on derelict vessels. It was different from other Commando-likes in that you could move in any direction around the map and didn''t just keep going up like most other such games.' FROM games WHERE igdb_id = 40472 ON CONFLICT (game_id, language_code) DO NOTHING;
