INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX5000', 'MX5000 is a scrolling shooter arcade game released by Konami in 1987. The goal for the player is to fly in the latest fighter aircraft of the Roufanis territory and fight with the Desalis empire which is trying to dominate the world. It is a title highly regarded by a selected few containing an interesting content including features such as a military-style worldview, simple controls and exciting BGM.' FROM games WHERE igdb_id = 40559 ON CONFLICT (game_id, language_code) DO NOTHING;
