INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: The Rebel Universe', 'The game places the user in control of the bridge crew of the Enterprise while they explore an area of space attempting to understand why all previous Federation ships that entered the region have mutinied. Each member of the bridge crew is in control of certain aspects of ship operations, allowing the player to control the mission through their stations. The user can also orbit above planets and beam down selected members in order to find devices or clues that can solve the mystery of the "Quarantine Zone".' FROM games WHERE igdb_id = 15376 ON CONFLICT (game_id, language_code) DO NOTHING;
