INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jinxter', 12160, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gpecg5pfefuber943e3v.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jinxter', 'Just when a man thinks his luck is running out, things start getting even worse. He gets run over by a bus. Sprayed with cheese sandwich by a supernatural being. Smashed against a tunnel by a speeding train. He gets incinerated, widdled on, folded, bent, spindled, mutilated and generally mucked about with. And in return? He gets the leading role in a perplexing, hilarious race against time and chance, set in a jinxed land menaced by the impending death of good fortune. Look on the bright side - it could be your luckiest move yet. Don''t expect tiresome trolls, obvious orcs, silly spells and wet, wimpish witches in JINXTER. Infuriating, enchanting, absurd and hilarious by turns, JINXTER will surprise you with every move you make. But don''t forget: every silver lining has a cloud.' FROM games WHERE igdb_id = 12160 ON CONFLICT (game_id, language_code) DO NOTHING;
