INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sláine: The Celtic Barbarian', 'In Sláine: The Celtic Barbarian you embark on a quest to liberate Lyonesse from the lingering evil of the Drune Wizards. As the titular hero, you must rescue the beautiful daughter of the last Drune from Small Sky Tower, for only she knows the secret name that will break the curse. Navigate through a unique real-time menu system called REFLEX, which adds urgency to your exploration, object interactions, and combat. Manage Slaine''s Warp rating, a dynamic stat affected by battles and replenished through various means, as you wield your mighty sword and unravel the mysteries of Lyonesse in this thrilling action-adventure game.' FROM games WHERE igdb_id = 53163 ON CONFLICT (game_id, language_code) DO NOTHING;
