INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('saint-seiya-ougon-densetsu', 48655, '1987-11-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa56x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc80r8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: Ougon Densetsu', 'Saint Seiya: Ougon Densetsu is an RPG based around the anime and manga series known as Saint Seiya. It was developed and published by Bandai in 1987 for the Famicom. The story of the game draws heavily from the first story arc of the series, from the beginning of the story to the fight with the Gold Saints. The game remains faithful to the original story while introducing some original elements. When the game came out, the story line was in the middle of the Gold Saints story arc. As a result, the last boss of the game is an original character. The actual final fight of the Gold Saints arc was carried over into this game''s sequel, Saint Seiya: Ougon Densetsu Kanketsu Hen. The gameplay mixes side scrolling action scenes to transport the character from place to place where he may have to jump over obstacles and fight basic enemies, with a turn based combat system against bosses and other significant battles. In order to be successful at these turn based battles, the player must distribute his power, or Cosmos, to various attributes before each attack. Failure to do so typically results in no damage dealt to the opponent, and a lot of damage received. When Life is lost, the main character can be revived, but if all Cosmos is lost, then the game is over.' FROM games WHERE igdb_id = 48655 ON CONFLICT (game_id, language_code) DO NOTHING;
