INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('army-moves', 11916, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g94.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8k61.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Moves', 'Army Moves is a one-player game which is divided into two parts. In part one, you drive a jeep and must avoid collision with other jeeps and being shot at by helicopters. Then, you fly around in a helicopter and the oject is to bring down airplanes without being shot at by the airplanes themselves, submarines, and any other ground fire. Make sure you land on the pad near the end.  In part two, you start out in the jungle and must jump from rock to rock without crashing into toucans (shoot at them to make them fly higher) and being blown to bits. Then you have to make your way to the general''s offices shooting soldiers on the way, and finally, locate the secret documents. When you complete the seven sections of Army Moves, you''ll receive a higher bonus.  Some versions have a high score table to record your achievements. The second section must be loaded seperately, using a code attained from completing part one, on some versions.' FROM games WHERE igdb_id = 11916 ON CONFLICT (game_id, language_code) DO NOTHING;
