INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Victory Run', 'Strap on this red turbo-charged beauty and punch it. Barrel through the streets of night-time Paris. Lean into the rolling countryside curves. Sweat the hot Sahara straightaway. The famous Paris to Dakar Road Rally tests driving skills, reaction time and your knowledge of the needs of your machine in various conditions. Great sights! Great sounds! If you''ve got the skills-hit the road, Jack. The best time wins!' FROM games WHERE igdb_id = 42118 ON CONFLICT (game_id, language_code) DO NOTHING;
