INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon''s Lair: Escape from Singe''s Castle', 'The adventure continues… The evil Shapeshifter has stolen Princess Daphne and to save her you will have to outwit the Evil One in totally new encounters never before seen in the original Dragon''s Lair. New scenarios and characters combine to make Escape from Singe''s Castle the best sequel to the largest selling animated adventure of all time… Dragon''s Lair. Muster all your skill and cunning to free Daphne from deep within the labyrinthian dungeons of Singes Castle. Lead on brave adventurer, your quest awaits!' FROM games WHERE igdb_id = 14659 ON CONFLICT (game_id, language_code) DO NOTHING;
