INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gaia-no-monshou', 42063, '1987-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ldk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8sly.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gaia no Monshou', 'Gaia no Monshō (also known as the ''Crest of Gaia'') is a fantasy round-based strategy game by NCS and conversion of a game originally released for the NEC PC-8801 in 1987. Gaia no Monshō is a turn-based strategy game at heart - the player moves troops around a battlefield and attacks nearby enemy units. An Auto Battle mode is also available and gives the option to let the AI figure out of the player''s next move. The game offers several play modes - the first one (Scenario Mode) gives the player the chance to jump straight into battle using predefined troops. The second (Construction Mode) allows him to build his own army using unit points. The last one (Campaign Mode) conveys story plot elements and starts in the siege town of Dirl, where king Sieghart battles the fierce Böser. This mode requires more complex strategy and the player must assemble his own troops using unit points and units lost in battle don''t come back during the campaign. Unlike the other two modes, it offers a password system to save the player''s progress through the game.' FROM games WHERE igdb_id = 42063 ON CONFLICT (game_id, language_code) DO NOTHING;
