INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sd-gundam-world-gachapon-senshi-scramble-wars', 41334, '1987-12-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4igv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gu2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SD Gundam World: Gachapon Senshi - Scramble Wars', 'Two teams, the blue army and the red army, compete on tiled maps in an attempt to vanquish one another in battle. Each team starts off in one particular portion of the map, usually but not always on opposite sides. Throughout the map are cities which start out neutral, but can be converted to the red or blue side through occupation. The more cities a team has, the more energy that team produces every round to direct toward the construction of newer and more powerful Gundams. Each team gets to issue three commands per turn, whether it be to move a Gundam around the map, or construct a new Gundam. Each type of robot has different ranges of movement, and different terrains effect how far a robot can travel. In order to destroy each other, players must attack the opposing team''s Gundams by moving one of their own to a tile occupied by the enemy. When two Gundams rest on the same spot, a battle is initiated.' FROM games WHERE igdb_id = 41334 ON CONFLICT (game_id, language_code) DO NOTHING;
