INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BodyConQuest I: Abakareshi Musume-tachi', 'BodyConQuest I: Abakareshi Musume-tachi is an unlicensed, 2 disk, action RPG, Dragon Quest parody. The plot is basic, in that the kings sends you to find his daughter who has a heart shaped birthmark on her buttocks. The game features an Ys / Hydlide like battle system, multiple towns with NPCs, dungeons, bosses, and the usual magic, items, and equipment. It also has a number of full screen images of women in various stages of dress. Although it''s two disks, it''s a relatively short game.' FROM games WHERE igdb_id = 41238 ON CONFLICT (game_id, language_code) DO NOTHING;
