INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Adventure Touch: Mystery of Triangle', 'CITY ADVENTURE touch MYSTERY OF TRIANGLE is an action game for the Famicom and NES system that was published by Toho in 1987. The game is based on the high school and baseball team themed manga Touch. City Adventure Touch is somewhat notorious in Japan for bearing absolutely no resemblance to the source material. A comic book concerning the Mystery of Triangle is included in the manual. The story appears to revolve around a character''s dog who disappears into an alternate dimension, and the three children who attempt to rescue it, one of which attacks by throwing baseballs.' FROM games WHERE igdb_id = 48315 ON CONFLICT (game_id, language_code) DO NOTHING;
