INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laplace no Ma', 'Laplace´s Demon is a Sweet Home-like RPG and it takes place in a suburb of Boston in 1924. You can pick from one of six or so classes at the start of the game (Detective, Journalist, Psychic, etc) and you can recruit other members, and it plays a lot like a normal RPG. It also seems to be one of the first games to pioneer a limit-break like system, which is now in use in a lot of games.' FROM games WHERE igdb_id = 81469 ON CONFLICT (game_id, language_code) DO NOTHING;
