INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outcast', 'Outcast is a ZX Spectrum 48K single-player arcade-adventure published by CRL Group PLC in 1987. You explore a multi-screen map, navigating hazards and enemies while collecting and using items to progress; gameplay is keyboard/joystick friendly with fully re-definable keys, and longplays show flip-screen exploration with action-heavy traversal and item management typical of Spectrum arcade-adventures of the era.' FROM games WHERE igdb_id = 15331 ON CONFLICT (game_id, language_code) DO NOTHING;
