INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Dogs', 'Deadly Discs fan Dave Warhol put together his own private version of the game, replacing the enemy warriors with the hot dogs from BurgerTime. He called the result Deadly Dogs. If you want to play it, it''s hidden in the INTV Corporation release of Dig Dug: press 47 (4 and 7 simultaneously) on both hand controllers and press reset. The Deadly Dogs title screen will appear.' FROM games WHERE igdb_id = 41476 ON CONFLICT (game_id, language_code) DO NOTHING;
