INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Wizard', 'Pinball Wizard is a German pinball game with one non-scrolling table. As usually, the goal is to use the three paddles to keep the ball as long as possible from falling off the screen. Hitting things on the playfield rewards points for the high score list which is saved on the disk. The table also features some additional extras to discover, e.g. hitting a certain spot when the letters "AMIGA" are glowing activates a multi ball. Also included is the option to influence the ball''s direction by nudging the screen - but this eventually leads to a tilt.' FROM games WHERE igdb_id = 260830 ON CONFLICT (game_id, language_code) DO NOTHING;
