INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-growing-pains-of-adrian-mole', 28439, '1987-02-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ll6wn2z4jhirfpw9wyib.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scdart.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Growing Pains of Adrian Mole', 'The game is an adventure of sorts, presenting you with 18 months of life viewed through the curious, confused and intellectual eyes of Adrian. Each section features a number of challenges, in which one of three choices on what to do must be made. As you play, the aim is to make Adrian as popular as possible by making the correct choices so as to exert a positive impression on Mum, Dad, Pandora, Nigel, Bert and all the rest. The game is split into four sections, which can be loaded individually or in sequence, with the score remaining in memory as you progress through them.' FROM games WHERE igdb_id = 28439 ON CONFLICT (game_id, language_code) DO NOTHING;
