INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krazy Kobra', 'It''s the classic game of Snake, except released back when it was still fairly new. This version however is an extreme challenge with 50 custom-designed levels to rival the mighty Snake Byte.' FROM games WHERE igdb_id = 94620 ON CONFLICT (game_id, language_code) DO NOTHING;
