INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Stealth Fighter', 'Rule the night! Take the pride of American Stealth technology and take on the best the Warsaw pact technology can offer! Dodge between radars, sneak under enemy fighters, and take out your primary objectives and secondary objectives with your limited weapons onboard, then make your way home. Can you survive all the way to general and win the Congressional Medal of Honor?' FROM games WHERE igdb_id = 10293 ON CONFLICT (game_id, language_code) DO NOTHING;
