INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elves ''87', 'You play as a retired Christmas elf, brought in at the last moment to help Santa to save Christmas... but first, you have to figure out what is wrong. Explore the North Pole and beyond, meet a few memorable Christmas characters, and save the day before Santa gets too drunk on fancy blended beverages' FROM games WHERE igdb_id = 246233 ON CONFLICT (game_id, language_code) DO NOTHING;
