INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Feud', 'Based on the television game show, Family Feud pits two teams of five against one another as they attempt to guess the top answers to survey questions. The winning team advances to the Fast Money round where they have two tries to guess answers to five questions as a timer counts down. Players can challenge the computer or a friend and name their team.' FROM games WHERE igdb_id = 145825 ON CONFLICT (game_id, language_code) DO NOTHING;
