INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Colditz Story', '''On a night bombing raid over Germany, your plane is shot down and you are captured. Now, as a prisoner of war in the notorious Colditz Castle, your one thought is to escape. You overpower a guard, take his gun and, using all your skill and cunning, set out on your quest for freedom. As you move around the castle, your position is shown on the right of the screen. The top display shows available exits whilst the whole castle map is shown at the bottom. The window of your current location will light up as you enter a room.' FROM games WHERE igdb_id = 14008 ON CONFLICT (game_id, language_code) DO NOTHING;
