INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crumble''s Crisis', 'It''s all your fault, Crumble! Now don''t stand there snivelling and whining! YOU were in charge of closing up the Intergalactic Zoo last night. Therefore it''s YOUR fault and yours alone that the timelocks on the Fuzzies cages weren''t closed. Those Fuzzies may look cute and cuddly but they''re mean little critters once they''re loose and somebody, one of us, has to get them back in their cages.' FROM games WHERE igdb_id = 159269 ON CONFLICT (game_id, language_code) DO NOTHING;
