INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Pinball', 'This is a spooky-themed pinball game. Obstructions appear within the table as you play. Gravestones, ghosts, and undead hands rising from below. Released in 1987, this Spanish pinball game was developed and published by Omikron. Outside the review (and a page ad) on Issue 42 of MSX Extra, listing on MSX Games World and a post on Instagram by MSX Calamar, not much is known about this obscure game.' FROM games WHERE igdb_id = 273530 ON CONFLICT (game_id, language_code) DO NOTHING;
