INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blazer', 'The player must alternate between a tank named "Vanguard" and a helicopter named "Maiheriko" (and for the tenth and final mission, a boat named "Maiboto"), to kill enemies both on land and in the air. Some air-based enemies will leave behind powerups for Vanguard to collect, when hit by its anti-aircraft missiles; they can restore its fuel, increase its fuel capacity, make it invulnerable for a short period of time, and even grant it an extra life if it manages to collect enough of them (which is initially thirteen, but it can go up to sixteen).' FROM games WHERE igdb_id = 46842 ON CONFLICT (game_id, language_code) DO NOTHING;
