INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Warden Game', 'The Warden Game is a text-adventure style game that helps players understand the contradictions of prison life in an age of mass incarceration. Designed by Ed Mead around 1987, while he was incarcerated at the Washington State Reformatory at Monroe, the game explores power in prison and how individuals exercise it.' FROM games WHERE igdb_id = 176077 ON CONFLICT (game_id, language_code) DO NOTHING;
