INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomb Sweeper', 'Bombsweeper was a multi-screen Game & Watch video game released in June of 1987. The game was never released in Japan. The game''s model number was BD-62. Using the D-pad to move John Solver, you must reach at least one of the bombs hidden in the walls to clear the screen and receive a bonus for the time remaining. The only obstacles in your path are the walls, which you must either maneuver around or push them along provided there is no obstruction in the way. Some levels are a test of speed, others are a test of logic and intelligence.' FROM games WHERE igdb_id = 145222 ON CONFLICT (game_id, language_code) DO NOTHING;
