INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doc the Destroyer', 'In this unique hybrid action RPG from 1987, take on the role of Doc the Destroyer, outcast and heretic in a post-apocalyptic wasteland, as he battles to save the dwellers of a life-saving dome from extinction. Make decisions in a branching storyline, and fight in one-on-one battle sequences.' FROM games WHERE igdb_id = 39737 ON CONFLICT (game_id, language_code) DO NOTHING;
