INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RealSports Boxing', 'RealSports Boxing is a boxing based video game developed by Atari and released in 1987 for the Atari 2600. It is part of the RealSports series of games from Atari. The game has a side view of the ring, allowing the player to move up and down, as well as from left to right. There are four selectable characters in the game, Lefty O''Leary, Jabbin'' Jack, Macho Man, or Iron Fists. The aim of the game is to knock out the opposition by filling up a bar at the bottom of the screen which allows the player to deliver the knock out blow. The game can be played with two players simultaneously.' FROM games WHERE igdb_id = 18417 ON CONFLICT (game_id, language_code) DO NOTHING;
