INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('famicom-grand-prix-f-1-race', 41251, '1987-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co227o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8569.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Famicom Grand Prix: F-1 Race', 'Famicom Grand Prix: F-1 Race is a Japan-exclusive racing game starring Mario in Formula One cars. In the game, players can choose to play alone or with other cars. Cars have a certain amount of health and fuel, which decreases whenever the player crashes into a wall or another car, as well as whenever he or she drives off of the road. This game, along with its sequel, was possibly an ancestor to the Mario Kart series, most likely due to the fact that it features Mario and possesses similar 2D racing mechanics, which was later carried on to Super Mario Kart.' FROM games WHERE igdb_id = 41251 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41251 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
