INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perfect Murder', 'Slovak murder simulator text adventure game in which the player can kill a person of their choosing (by entering their name) and then cover up the tracks. One can explicitly choose to murder an "unpopular politician." Received an English translation in 2021 as part of an initiative by the Slovak Game Developers Association in cooperation with Slovak Design Museum, with funding by the Slovak Arts Council.' FROM games WHERE igdb_id = 209444 ON CONFLICT (game_id, language_code) DO NOTHING;
