INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Mission', 'Following a robot rebellion, humans have fled the Earth for the planet Nova. They have sent the robot OR-CABE-3 back to Earth to obtain the secret defense plans of the enemy robot base. The player takes control of OR-CABE-3 as it attempts to escape the enemy base with the plans and board a spacecraft for Nova.' FROM games WHERE igdb_id = 41798 ON CONFLICT (game_id, language_code) DO NOTHING;
