INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ancient Art of War at Sea', 'The Ancient Art of War at Sea is a strategy game that includes a powerful game generator. So you can actually create your own naval battles, determine every detail, from the makeup of the fleets to the danger of the waters they''ll sail in. Even design your own continents and oceans. Then, when you''ve played your game, you can save it or alter it to play again and again.' FROM games WHERE igdb_id = 41069 ON CONFLICT (game_id, language_code) DO NOTHING;
