INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('habitat--4', 192111, '1987-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ili.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scfvvk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Habitat', 'Habitat is a pioneering massive multiplayer online game (MMO) developed by Lucasfilm Games that laid the foundation for modern MMORPGs. Released as a beta test on Quantum Link''s online service, it allowed up to 500 players to simultaneously explore a vast, open-ended virtual world. Despite lacking traditional RPG elements like leveling or classes, Habitat broke new ground by offering a persistent, shared environment where players could interact through customizable avatars in a 2D, third-person perspective. The game''s emphasis on social interaction and player-driven content was revolutionary for its time. Players could engage in a wide range of activities, from simple communication and object manipulation to complex social endeavors like marriage, commerce, and even founding religions or guilds. The game world, comprised of thousands of diverse regions, encouraged exploration and discovery. Habitat''s innovative features, including an in-game economy, player-run businesses, and global quests organized by the developers themselves, showcased the potential of virtual worlds as social platforms. This libertarian approach to gameplay, where players were limited only by the game''s code, set a precedent for user-generated content and emergent gameplay in online worlds, influencing the development of future MMORPGs and virtual communities.' FROM games WHERE igdb_id = 192111 ON CONFLICT (game_id, language_code) DO NOTHING;
