INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wiz', 'The good land of Midgard and the evil land of Neflheim have long been joined together by a powerful spell, which has long been acceptable, but now the evil is starting to seep through. As a novice Wizard you aim to earn enough points to become a top-level wizard and cast the spell which might blast the worlds apart. Unfortunately, the powerful wizards feel this is too dangerous, and will set out to stop you any way they can.' FROM games WHERE igdb_id = 47151 ON CONFLICT (game_id, language_code) DO NOTHING;
