INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peur Sur Amityville', 'The player takes on the role of the father of a family that moves into the Amityville haunted house. Little by little, the house comes to life and he has to face more and more horrible events. He is a prisoner of the house and the goal is to get out alive after 24 days.' FROM games WHERE igdb_id = 174635 ON CONFLICT (game_id, language_code) DO NOTHING;
