INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikai Shounen Mettomag', 'The player must solve 100 puzzles in the form of rooms that contain magnetized squares. The player assumes either a North or South magnet polarity as he or she collects all of the polarity orbs in each room before attempting to reach the exit. The polarity of the player affects how he or she interacts with the magnetized squares which can enable or hinder the player in his or her progress through the level.' FROM games WHERE igdb_id = 41321 ON CONFLICT (game_id, language_code) DO NOTHING;
