INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xor', 'A 2D puzzle game. The player controls two shields, Magus and Questor, which can be moved horizontally and vertically though the maze, in order to collect masks. The object of each level is to collect all the masks, then reach the exit. In all levels, use of both shields are required for completion, and in some, one shield must be sacrificed (walled in or destroyed) in order to complete the level.' FROM games WHERE igdb_id = 54669 ON CONFLICT (game_id, language_code) DO NOTHING;
