INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blow-up', 47556, '1987-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blow Up!', 'In Blow Up! the player takes on the role of Joe Kowalski who must navigate his way to the exit in six progressively more difficult caverns. The game has similar gameplay as Boulder Dash, and each cavern must be completed within five minutes.  Along the way, Joe will encounter various enemies. There are grabbers who will jump on Joe and slow him down. Darth Vader heads who move around more quickly and will shoot at you. Walking grenades will explode when you come too close to them. The green virus will spread around when it is unleashed and it will make you sick when you come into contact with it. Joe will turn pale white, his energy will drain and he can only move around slowly.  Joe can fight back by dropping rocks onto them, or by shooting them or by using mines to blow up enemies or walls.' FROM games WHERE igdb_id = 47556 ON CONFLICT (game_id, language_code) DO NOTHING;
