INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('seiken-psycho-calibur', 41248, '1987-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cohsan8r2ipzu7av2ylf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seiken: Psycho Calibur', 'Many years ago there was a country called Earth Maral. One day it was invaded by the forces of the Dark World and torn apart. People lived in fear, there only hope a legend…  ''A hero holding a sword will appear and restore peace to our land once again.''  No one knew when this hero would arrive…  Said the devil beast: "What''s that? You challenge me? I see. Very well then. I accept your challenge. However, you will never win!"' FROM games WHERE igdb_id = 41248 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41248 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
