INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Prix Simulator', 'There were up to 14 circuits depending on the format, which incorporated many underpasses (some of them deliberately unrealistic) and tight curves. There were oil slicks to avoid and points bonuses to pick up. The cars have slow acceleration but a lot of power down the straights. You are scored based on your overall time and your fastest lap. Lose to the computer car and it''s game over.' FROM games WHERE igdb_id = 13861 ON CONFLICT (game_id, language_code) DO NOTHING;
