INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quarterback', 'The Leland Corporation presents QUARTERBACK, the most exciting football game ever. This is football the way it was meant to be, with all the action and all the strategy. Players call their owna plays and the spring-loaded joystick gives them complete control of the passing and the kicking game. The exclusive individual stat storage feature keeps players coming back for new and even more challenging games. This is real football with game play that could only come from the people at the Leland Corporation.' FROM games WHERE igdb_id = 46853 ON CONFLICT (game_id, language_code) DO NOTHING;
