INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pi-r-squared', 41147, '1987-02-01', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/k3tmtouwra04mbuhoezx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pi R Squared', 'In this logical game you have to move a sphere around cogs to collect a formula in the correct order. To move between cogs you press the space bar at the point they meet. Holding down W will allow you to move the opposite way the cog is moving but here you move slower, releasing W allows you to travel faster the way the cog is moving. Some cogs have baddies on them and you must time your transfer to it without being hit by it.  On the screen you see a small part of the game area. As well as the main playing area you can also see your score, lives, level and parts of the formula collected.' FROM games WHERE igdb_id = 41147 ON CONFLICT (game_id, language_code) DO NOTHING;
