INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seilane', 'Seilane can be considered a classic adventure game that follows a command selection system. Players choose commands such as "talk," "call," "listen," "examine," and "eat" depending on the scene, advancing the scenario accordingly. . Players take on the role of a field mouse named Prill and embark on an adventure to rescue the animals of a village turned to stone by the Demon King Pazul, as well as his kidnapped sister.' FROM games WHERE igdb_id = 92130 ON CONFLICT (game_id, language_code) DO NOTHING;
