INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega One', 'You have 12 hours to destroy the Omega One Space complex. Very little information is know about the complex, other than it is located on 10 planets connected by a series of teleports. If you are caught, steps have been taken by your employers to ensure you reveal no secret information..let''s hope you don''t have to find out what those steps are exactly.....' FROM games WHERE igdb_id = 55016 ON CONFLICT (game_id, language_code) DO NOTHING;
