INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beneath Folly', 'The folly stands a top Folly Hill in Oxfordshire and legend has it beneath the rock is caves where The Fiend lives. His master plan is to enslave all adventure players as he finds them all stupid. You are one player and must escape the caves and outwit The Fiend to find freedom. Beneath Folly is a graphical text adventure where you can see a picture showing your surroundings as well as a text description describing them. You type in commands to solve the puzzles and find freedom.' FROM games WHERE igdb_id = 229214 ON CONFLICT (game_id, language_code) DO NOTHING;
