INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enlightenment: Druid II', 'One hundred years after Hasrinaxx the Druid defeated the evil Acamantor, his nemesis is back, and although now older and having lost his Druid status after experimenting in black arts, he feels worthy of banishing this terrible foe.  The gameplay uses a forced perspective top-down view, and strongly resembles Gauntlet in the way Hasrinaxx moves, shoots, avoids enemies and collects health items.' FROM games WHERE igdb_id = 12585 ON CONFLICT (game_id, language_code) DO NOTHING;
