INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Byouin', 'Patients begin to die one by one under mysterious circumstances in a mental hospital. A young nurse named Ikuko Matsuda doubts that these deaths were natural. On day, Ikuko disappears, leaving behind a blood-stained cash card. Her fiance Katsuyoshi Yamazaki ventures into the hospital, attempting to investigate the mystery.' FROM games WHERE igdb_id = 230206 ON CONFLICT (game_id, language_code) DO NOTHING;
