INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nether Earth', 'Nether Earth is a realtime strategy game that takes place in the distant future. A war is being waged between humans and ancient race of aliens called Insignian. On their mysterious planet there are four bases to capture - Kerberus, Tarras, Faretra and Diolkos. Use factories to build giant battle robots, similar to Mech units in other games. Commanding robots, capturing factories and defeating enemies in realtime are the player''s primary goals.' FROM games WHERE igdb_id = 38744 ON CONFLICT (game_id, language_code) DO NOTHING;
