INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chip Shot: Super Pro Golf', 'Chip Shot: Super Pro Golf is 1-2 player golfing game where you play 9 or 18 holes, choosing from 1 of 5 courses of varying difficulty. Play with a bag of 14 clubs. Shoot over trees, sand traps, and water hazards. The game features variable swing speed, hook, slice, wind, zoomed in putting terrain, and a course designer.' FROM games WHERE igdb_id = 41438 ON CONFLICT (game_id, language_code) DO NOTHING;
