INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fuksoft', 'Slovak text adventure game, likely the first Czechoslovak homebrew title to feature autobiographical elements within the game''s narrative. Title and characters are an homage to Fuxoft. Takes place in a Czechoslovak apartment building, with gameplay based on map navigation and puzzle-solving against a time limit, controlled by keyboard shortcuts rather than typed-in commands. Received an English translation in 2021 as part of an initiative by the Slovak Game Developers Association in cooperation with Slovak Design Museum, with funding by the Slovak Arts Council.' FROM games WHERE igdb_id = 209439 ON CONFLICT (game_id, language_code) DO NOTHING;
