INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenshi-tachi no Gogo II: Minako', 'The sequel to "Tenshi-tachi no Gogo"; instead of playing as the obnoxious male protagonist of the previous game, the player takes control of Minako, a female Japanese high-school student with a strong interest towards sexuality. The story mainly depicts Minako''s sexual encounters with men and women, which take place on school grounds, in various locations of the city, etc.' FROM games WHERE igdb_id = 247182 ON CONFLICT (game_id, language_code) DO NOTHING;
