INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Valley', 'ARCHEULT, el terrorífico y poderoso líder del Firedrake, ha ordenado que te den caza y te sentencien. Tu única posibilidad de supervivencia es escapar del Valle.  ¿Posees la valentía y los recursos suficientes para vencer no sólo a tu adversario sino también a todas las criaturas y seres tenebrosos del mundo fantástico de Orb?' FROM games WHERE igdb_id = 13410 ON CONFLICT (game_id, language_code) DO NOTHING;
