INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roadwars', 'A 1-on-1 3-D shoot-em''-up in which one or two players drive battlespheres (futuristic tanks) up an infinitely long road and destroy oncoming hazards. The action is very simplistic and there''s little to do other than dodge or blast approaching objects.' FROM games WHERE igdb_id = 12843 ON CONFLICT (game_id, language_code) DO NOTHING;
