INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bolo', 'An early networking experiment between BBC microcomputers, Bolo is a top-down tank deathmatch game with a highly simplified physics model, allowing the player not only to move through and among 10 different terrain types, shoot, lay mines, and capture and deploy automated pillbox turrets, but also build speed-enhancing roads, sheltering walls, and water-traversing boats and bridges through judicious use of his lumber-collecting Little Green Man (LGM). Toward what end? Why, the capture of refueling bases and defense of them against enemy human- or computer-controlled tanks.' FROM games WHERE igdb_id = 95468 ON CONFLICT (game_id, language_code) DO NOTHING;
