INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kinetik', 'Kinetik is an arcade adventure which features gravity, inertia and other real physics heavily. You control a round spaceship, which must be guided through the 44+ screens. Collect the letters P,A and X in that order and reach the end to win.' FROM games WHERE igdb_id = 41060 ON CONFLICT (game_id, language_code) DO NOTHING;
