INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masters of the Universe: The Arcade Game', 'Masters of the Universe: The Arcade Game is a platform game developed by Adventure Soft for the Amstrad CPC, BBC Micro, Commodore 64, and ZX Spectrum and published by U.S. Gold in 1987. The game is part of the Masters of the Universe media franchise. The Commodore 64 version is titled He-Man and the Masters of the Universe: The Ilearth Stone.' FROM games WHERE igdb_id = 8157 ON CONFLICT (game_id, language_code) DO NOTHING;
