INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sesame Street Pals Around Town', 'Pals Around Town is a computer game published by Hi Tech Expressions in 1987 and programmed by Children''s Television Workshop. It was released for the Atari and the IBM PCjr in cartridge form. The basis for the game was strictly educational. The player could pick a character (Sesame Street characters available included Bert and Ernie, among others) and could interact with various objects in a variety of settings. Two such settings were a school classroom and an outdoor playground. Some items that could be interacted with included a fishbowl and a globe.' FROM games WHERE igdb_id = 213177 ON CONFLICT (game_id, language_code) DO NOTHING;
