INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cruncher-factory', 12555, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/hifdtvuy7onjlalwlb6b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nvebmbumuiwwbrdg8bhd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cruncher Factory', 'Cruncher Factory is a Pac-Man variant. The player commands a cruncher (which looks exactly like Pac-Man) and steers him through non-scrolling labyrinths shown from the side. On every place not occupied with a wall are pills which have to be eaten by rolling over the field they are on. There are also ghosts which cause the player to lose a life when touched - at least until the cruncher eats a special ball which causes him to eat the ghosts. A level is won when all balls are eaten. The game features 100 levels, a level editor (can be also used to change the existing levels) and a two-player mode.' FROM games WHERE igdb_id = 12555 ON CONFLICT (game_id, language_code) DO NOTHING;
