INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Lode Runner', 'The game keeps the typical gameplay of the Lode Runner series. Players have to collect all the gold on the stage, while either avoiding or trapping the robotic guards who are constantly giving them chase. The game also features a level editor so players can create their own stages to play on.' FROM games WHERE igdb_id = 41320 ON CONFLICT (game_id, language_code) DO NOTHING;
