INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Devil Story: Megami Tensei', 'Digital Devil Story: Megami Tensei is an action RPG developed by Telenet Japan, based on a manga of the same name. Despite sharing a name and source material with the Atlus developed Famicom game, it is an entirely different game. The player is tasked with traveling through the Makai, which is divided between eleven worlds themed after the Sephirot. Each of the worlds contains eight floors, though they are not always arranged in ascending order. Each world, other than the starting world Malkuth and the center world Da''at, is further divided into "good" and "evil" versions, for a total of 160 floors.' FROM games WHERE igdb_id = 136113 ON CONFLICT (game_id, language_code) DO NOTHING;
