INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Stig IV', 'A Slovak text adventure recently re-released in English based around the subject of computer hacking and system penetration. It is an unofficial sequel to The Stig 3, by Fuxoft and there is important info that can help a user in this game. The story takes place in the (then) near future of 1991 in New York. You play as Tim Coleman, a programmer\hacker and your job is to hack Jack Ragger and clean out his accounts.' FROM games WHERE igdb_id = 243909 ON CONFLICT (game_id, language_code) DO NOTHING;
