INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exzisus', 'Exzisus was produced by Taito in 1987. Taito released 403 different machines in our database under this trade name, starting in 1967. Other machines made by Taito during the time period Exzisus was produced include Arkanoid - Revenge Of Doh, Double Dragon, Dr. Toppel Tankentai, Flying Shark, Hishou Same, Great Gurianos, Inspiration Baseball, Tokio, Storming Party, and Soldier Of Light.' FROM games WHERE igdb_id = 39896 ON CONFLICT (game_id, language_code) DO NOTHING;
