INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amegas', 'Amegas is a wild, fast paced game written to take full advantage of the Amiga''s amazing speed, graphics and sound! Bounce, shoot, slam, and juggle your way through 40 challenging screens. Every screen has its own surprises and it will take quick reflexes to deal with all the action, sounds, and sights! For the Amiga 500, 1000 and 2000.' FROM games WHERE igdb_id = 11898 ON CONFLICT (game_id, language_code) DO NOTHING;
