INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '''Er*Bert', 'A cubic-domain game in which you must change the colour of the grid and avoid the gorilla, balls and snake. Starring : Crazy Er*Bert Supporting cast : Boris the Gorilla, Coily the Snake Featuring : Cascading balls, deadly discs, balmy bananas, rotating rota-hats Great fun in this arcade-style classic!' FROM games WHERE igdb_id = 98236 ON CONFLICT (game_id, language_code) DO NOTHING;
