INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('munchman-ii', 42171, '1987-02-01', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Munchman II', 'Munchman II is a sequel to the original Munchman, Texas Instruments'' own variant of Pac-Man. While the first game had the munchman laying down a chain throughout the maze, this game is more like a traditional Pac-Man game with the player having to eat all the chains. There are four enemies called hoonos attempting to kill the munchman but by eating an energizer it can for a short while go after and kill them.  Some new features set the game apart from other Pac-Man games. The maze is made up of two interconnected screens that the player can move between through two doors. To complete a level the chains of both screens have to be eaten. Another feature is the teleporter that roam around the maze. By running into it the munchman is transported to the other screen.  There are two modes of play: arcade and tournament. In the arcade mode the player has three lives and earns an extra one after every 10,000 points scored. In the tournament mode there is only one life and no extra ones can be earned.' FROM games WHERE igdb_id = 42171 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 42171 AND p.igdb_id = 129 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marchen-veil', 41337, '1987-04-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7s4m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmtox.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marchen Veil', 'The king of the Country of Forest in Felix sent out a proclamation all throughout Felix announcing that he was seeking a suitable young man to take his beloved daughter as a bride. Many suitors responded and were subsequently put through a large variety of trials by the king. In the end, the decision was narrowed down to two suitors. One was the prince of the Country of Lakes in Felix, and the other was a wizard who had used his powers to transform himself into a handsome young man. The princess'' heart was set upon the prince of the Country of Lakes, and the two proclaimed their love for one another with an oath. However, after learning about this, the wizard transformed himself into the shape of the prince in order to take the princess for himself. He placed a curse upon the prince and transported him far from Felix, to the other end of the world.' FROM games WHERE igdb_id = 41337 ON CONFLICT (game_id, language_code) DO NOTHING;
