INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros.', 'A special edition of Game & Watch Super Mario Bros. It was a prize for the Famicon''s F-1 Grand Prix tournament on August 1, 1987 with the code YM-901-S. It is a single-screen single-player game with a yellow case. It came in a plastic box modeled after Disk-kun, the Famicom Disk System mascot. This edition is the rarest of all Game & Watch models, with only 10,000 units produced and never available at retail.' FROM games WHERE igdb_id = 206934 ON CONFLICT (game_id, language_code) DO NOTHING;
