INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dunjunz', 'Dunjunz is an action game made for the BBC Micro and Acorn Electron home computers and released by Bug-Byte in 1987. It is essentially a clone of the popular video game Gauntlet where players controlled fantasy characters from a top down view. Unlike Gauntlet, each of the characters is given their own viewport onto the dungeon and can explore independently.' FROM games WHERE igdb_id = 134123 ON CONFLICT (game_id, language_code) DO NOTHING;
