INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anarchy', 'Viewed from above in levels with simple sideways scrolling, the objective on each level is to shoot each of the weapons crates, before going through the newly-opened exit. Guard droids must be avoided, but shooting them can leave them inactive for a short period of time, and they can now be shot or hit to push them in that direction, which can be used strategically to make more paths available. There is a 2-minute time limit on each level. Every 5th level has a nuclear weapon guarded by a seeking enemy droid, which continually follows you.' FROM games WHERE igdb_id = 13318 ON CONFLICT (game_id, language_code) DO NOTHING;
