INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game de Check! Koutsuu Anzen', 'Game de Check! Koutsuu Anzen is an educational game that was commisionned by a Japanese insurance company, and was never actually on sale. They made a couple of hundred copies, and would lend the game, along with a Master System, to primary schools that requested it.' FROM games WHERE igdb_id = 268899 ON CONFLICT (game_id, language_code) DO NOTHING;
