INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El Cid', 'In the eleventh century a parchment was left on the Earth. On it was inscribed a diabolical magic which could unchain the forces of evil and guarantee Satan''s supremacy as the Prince of Darkness. Rodrigo Diaz, ''El Cid'', a gallant knight, was aware of the terrible threat and vowed to find the spell and guard it until it could be neutralised by two men of prayer' FROM games WHERE igdb_id = 13629 ON CONFLICT (game_id, language_code) DO NOTHING;
