INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Santa Claus no Takara-bako', 'One month a year, we celebrate this season, thank you for the wonderful memories. And in appreciation for this year, while people send the gifts, Christmas is for us a time to round off the memories of one year, a time to give those close words of gratitude in a Christmas card. Thank you for the wonderful memories this year. With feeling of gratitude, our gift to you. Merry Christmas.' FROM games WHERE igdb_id = 41250 ON CONFLICT (game_id, language_code) DO NOTHING;
