INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Otocky', 'Otocky can be described as a musical side-scrolling shoot ''em up. The player''s spaceship has a ball for a weapon, which can be fired in eight directions; each direction corresponds to a different musical note. The note plays when the player presses the fire button, and is also quantized in time so that it matches the beat playing in the background. By using the weapon selectively the player can improvise music while playing.' FROM games WHERE igdb_id = 41234 ON CONFLICT (game_id, language_code) DO NOTHING;
