INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cogan''s Run', 'Cogan''s Run is a 2D side scrolling action/platform game, a little similar to Impossible Mission. The player controls an agent, who must find a control terminal. He fights against various robots, but has limited ammo. The main aspect of the game is using teleporters, elevators and switches on the walls in order to unlock certain paths and go further.' FROM games WHERE igdb_id = 113992 ON CONFLICT (game_id, language_code) DO NOTHING;
