INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nankoku-shirei-spy-vs-spy', 48812, '1987-04-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co749n.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nankoku Shirei!! Spy vs. Spy', 'Spy vs Spy: The Island Caper is a competitive multiplayer game where the goal is to recover all the vital items and leave before the other player does the same. It''s a tropical-themed variant on the original. The Island Caper plays almost identically to the original Spy vs Spy game, just with a graphically updated island theme. Instead of rooms full of fixtures that items might be hidden behind, the player must search beaches on islands for items buried in the sand. Specifically, they need to assemble a missile from its parts, presumably so it can be launched at the opponent spy''s home country. Finding the missile will allow the victorious spy to escape the island via a submarine (which inexplicably also includes an attractive woman). There are also traps which, like in the original, can be placed in spots where missile parts might be to fool opponents into killing themselves. The game was released on many of the home computers and consoles active at the time. Curiously, it also received a Japan-only NES port named "Nangoku Shirei!! Spy vs Spy" published by Kemco.' FROM games WHERE igdb_id = 48812 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 48812 AND c.slug = 'kemco' ON CONFLICT DO NOTHING;
