INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('profanation', 304127, '1987-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8agz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsjvr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Profanation', 'Profanation is an action game, where the player controls a fearless adventurer on his way to the mystical doors leading to hell. Entering a devilish castle with his only friend, a superb rifle, the adventurer should find a door on the level, collecting the treasures and eliminating their guardians such as bats, blobs of slime, zombies, insects and giant flies. The found door transfers the adventurer to the next level. When the adventurer is collided with an enemy, he is transferred to the most recent stored position on the level without one of his lives. Losing all the lives leads to the end of the game.' FROM games WHERE igdb_id = 304127 ON CONFLICT (game_id, language_code) DO NOTHING;
