INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('danger-street', 304126, '1987-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8agy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsjvm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danger Street', 'Danger Street is an arcade game set in New York 2017, a superb city filled with most infamous criminals in the entire galaxy. The highest council of New York has decided to finish it once and for all and massively eliminate these scums. The player is the vigilante of the future, who must rid the city of all these decadent beings. New York is counting on you! So, the player should shoot the enemies appearing on the screen and shooting at you with an aiming crosshair while scrolling the street from left to right. Once all the enemies are eliminated on the level, the player is transferred to the next level gaining the scores and the bonus. There is no health bar, and it is only one life for the player.' FROM games WHERE igdb_id = 304126 ON CONFLICT (game_id, language_code) DO NOTHING;
