INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starship Hector', 'Your ship is equipped with both a standard laser and an independently fired ground weapon, which you must coordinate to defeat ground and aerial enemies. A shield bar keeps track of your damage and you can replenish it by defeating certain enemies, but otherwise its just you, your ship and several stages of alien enemies that alternate between top-down and side-scrolling perspectives.' FROM games WHERE igdb_id = 48238 ON CONFLICT (game_id, language_code) DO NOTHING;
