INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midi Maze', 'MIDI Maze is a networked first-person shooter maze game for up to 16 players. The game area occupies only roughly a quarter of the screen and consists of a first-person view of a flat-shaded maze with a crosshair in the middle. All players are shown as Pac-Man-like smiley avatars in various colors. Bullets are represented as small spheres. The game is said to have introduced deathmatch combat to gaming in 1987' FROM games WHERE igdb_id = 15265 ON CONFLICT (game_id, language_code) DO NOTHING;
