INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thundercade', 'A nuclear powerplant has fallen into the hands of terrorists and you pilot a motorcyle equipped with machine guns that can be improved along the way. Make your way through difficult terrain and battle against loads of terrorists on foot, in cars, tanks and submarines who will try to stop you. Reach the plant and shoot all the terrorists to save the day.' FROM games WHERE igdb_id = 40480 ON CONFLICT (game_id, language_code) DO NOTHING;
