INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jongbou', 'Jongbou is a combination of a Breakout-style arcade game and a Mahjong game. The player can either beat a level by removing all bricks from the screen or finish a valid Mahjong hand by collecting the falling bricks that turned to Mahjong pieces. In the original arcade version the player is rewarded with a picture of an anime-style girl in a sexy outfit after each level. These bonus pictures have been removed from the Nintendo Famicom version.' FROM games WHERE igdb_id = 92298 ON CONFLICT (game_id, language_code) DO NOTHING;
