INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kid-no-hore-hore-daisakusen', 40237, '1987-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8iwu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclr3r.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid no Hore Hore Daisakusen', 'Before the SNES adaptation, Nichibitsu had actually licensed the Heiankyo Alien game in order to create its Kid no Hore Hore Daisakusen series. Although it features hole digging/enemy trapping mechanic, it''s hardly the trap-''em-up that Heiankyo Alien is. The real goal of each level is to collect all the items available to exit the level through a door. With the use of other items such as flame throwers and bombs, you could play through the entire game without once trapping an enemy. The game had several sequels, including Booby Kids for the Famicom and Doraemon Meikyū Daisakusen for the PC Engine. The latter was localized and released on the TurboGrafx-16 under the title Cratermaze, with the Doraemon character removed.' FROM games WHERE igdb_id = 40237 ON CONFLICT (game_id, language_code) DO NOTHING;
