INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathlord', 'The ninth Emperor of the Kingdom of Kodan has sent out the call for adventurers to put a stop the darkness that has fallen over his land and ultimately, to confront the Deathlord. As an oriental flavored RPG from EA, the game introduced a number of innovative features.' FROM games WHERE igdb_id = 13838 ON CONFLICT (game_id, language_code) DO NOTHING;
