INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meikyuu-hunter-g', 231407, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7qba.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meikyuu Hunter G', 'Meikyuu Hunter G is a multi-directional shooter arcade game which got released by Data East Corporation in 1987, only in Japan; however, it was later adapted by Data East USA as The Real Ghostbusters (under the license from Columbia Pictures Television, as it had been based on their animated series of the same name) for the United States later that year, and added a third yellow-suited player (Egon Spengler, as the unnamed blue- and red-suited protagonists for this original Japanese version became Peter Venkman and Ray Stantz). Two extra stages and an ending sequence were also added for the US version as the original Japanese one started over after the eighth one, along with several new powerups (including Slimer, although he is only referred to as "Green Ghost") and ghosts that appear after the unnamed enemies are killed (which can be beamed up, and put into "Ghost Storage" at the end of a stage); beaming up 100 ghosts is worth an extra life.' FROM games WHERE igdb_id = 231407 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 231407 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
