INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 231407 AND p.igdb_id = 52 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cracked', 11298, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mn0uawfmmry6gduab4nl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qyeknmgf5wimnbof7gd4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crack''ed', 'Crack''ed was developed concurrently for the Atari 2600 and 7800, but only the 7800 version was released. The 2600 version only has three levels as opposed to six on the 7800, but those three levels are well utilized considering the limitations of the 2600. As an Ornithologist, you must protect the eggs of the South American Hornbill that are nested in your tree. Various predators attempt to steal the eggs from under your nose. Using your slingshot, you must defend the eggs until the timer runs out. If a predator steals an egg you still have a chance to save it, but you risk losing other eggs from the tree while you are distracted. Next you must protect the Hornbills that have chosen to nest in the sewers, where the gameplay is the same as the tree level. Finally you move onto a bonus round at the Rooster Ranch, here you must shoot roosters that pop out of windows. The Atari 2600 version of Crack''ed was released at the 2002 Classic Gaming Expo, complete with a unique label, box and instructions.' FROM games WHERE igdb_id = 11298 ON CONFLICT (game_id, language_code) DO NOTHING;
