INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dondra: A New Beginning', 'Dondra: A New Beginning is an adventure game with cartoon-style visuals and text input. The protagonist is called forth from this world to another dimension to defeat the evil Colnar. The goal is to travel the world of Questmaster, find and defeat him, and find the prism. Along the way are various pitfalls and real-time traps and monsters.' FROM games WHERE igdb_id = 73987 ON CONFLICT (game_id, language_code) DO NOTHING;
