INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doremikko', 'A music game developed by Konami for the Famicom Disk System and published in late 1987. Like a few other music games of its kind, it comes complete with a digital keyboard which connects to the Famicom for the purpose of composing and playing music. The inclusion of a large keyboard with the game makes Doremikko the most expensive Famicom Disk System title at the time of its original sale. The name is a play on the Do Re Mi scale.' FROM games WHERE igdb_id = 41315 ON CONFLICT (game_id, language_code) DO NOTHING;
