INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('esper-dream--1', 47243, '1987-02-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91zi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv37n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Esper Dream', 'Brick Town, a town within a storybook, is in peril! Evil forces have descended upon the land and kidnapped the mayor''s daughter. And it just so happens that you have ESP. Thus it descends upon you - and your gun - to save Brick Town. Unlike most other RPGs of the time, Esper Dream isn''t based on medieval times, but rather on a fairy tale storybook of five chapters, each with a setting that is distinct from each other (they also contain sub-dungeons). Battles are started when the player runs into various pairs of moving footprints on the ground. This takes the player to a separate enclosed battlefield. There the player can use their weapons (or ESP powers) to defeat their enemies. Winning battles will increase the player''s character''s experience points, eventually leveling them up when they reach certain experience point totals. Leveling up increases their Hit Points {HP} and ESP Points {EP}. The player can also buy weapons by using the Gold Pieces that defeated enemies leave behind. The game is over when the player''s HP reaches zero - or when the player has successfully saved Brick Town from the evil scourge. Up to three save slots are available. They allow players the opportunity to save their progress and return to their adventure at a later date.' FROM games WHERE igdb_id = 47243 ON CONFLICT (game_id, language_code) DO NOTHING;
